ALTER TABLE public.expense_bill_allocations ADD COLUMN IF NOT EXISTS prepaid_schedule_id uuid REFERENCES public.prepaid_schedules(id), ADD COLUMN IF NOT EXISTS prepaid_expense_account_id uuid REFERENCES public.chart_of_accounts(id);
CREATE OR REPLACE FUNCTION public.finance_advance_contract_prepare(t uuid,ident uuid) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b expense_bills;r expense_recurring_rules;a expense_bill_allocations;s prepaid_schedules;pre uuid;firstdate date;lastdate date;cur date;lastmonth date;part numeric;remaining numeric;days integer;months integer;n integer:=0;BEGIN IF NOT finance_schedule_manager(t) THEN RAISE EXCEPTION 'Owner or admin required';END IF;PERFORM pg_advisory_xact_lock(hashtextextended('schedule:'||t::text,0));SELECT * INTO b FROM expense_bills WHERE tenant_id=t AND id=ident FOR UPDATE;IF b.id IS NULL OR b.approval_status NOT IN('draft','pending_review','approved') THEN RAISE EXCEPTION 'Unposted bill required';END IF;SELECT * INTO r FROM expense_recurring_rules WHERE tenant_id=t AND id=b.recurring_rule_id AND is_contract AND billed_when='advance' AND direction='cost';IF r.id IS NULL THEN RETURN 0;END IF;PERFORM finance_assert_open(t,b.bill_date);firstdate:=coalesce(b.service_period_start,b.period_start);lastdate:=coalesce(b.service_period_end,b.period_end);IF firstdate IS NULL OR lastdate IS NULL OR lastdate<firstdate OR lastdate>firstdate+interval '10 years' THEN RAISE EXCEPTION 'Confirm advance bill coverage dates';END IF;days:=lastdate-firstdate+1;months:=extract(year FROM lastdate)::int*12+extract(month FROM lastdate)::int-extract(year FROM firstdate)::int*12-extract(month FROM firstdate)::int+1;pre:=finance_schedule_account(t,'1320','Prepayments','asset');
FOR a IN SELECT * FROM expense_bill_allocations WHERE tenant_id=t AND bill_id=b.id FOR UPDATE LOOP IF a.capitalize OR a.amount<=0 THEN RAISE EXCEPTION 'Advance contract requires positive cost lines, not assets';END IF;IF a.prepaid_schedule_id IS NOT NULL THEN SELECT * INTO s FROM prepaid_schedules WHERE tenant_id=t AND id=a.prepaid_schedule_id FOR UPDATE;IF s.initial_journal_entry_id IS NOT NULL THEN RAISE EXCEPTION 'Already funded schedule cannot be changed';END IF;IF s.total_amount=a.amount AND s.start_period=date_trunc('month',firstdate)::date AND s.num_periods=months THEN CONTINUE;END IF;UPDATE prepaid_schedules SET status='cancelled' WHERE tenant_id=t AND id=s.id;END IF;
IF NOT EXISTS(SELECT 1 FROM chart_of_accounts WHERE tenant_id=t AND id=coalesce(a.prepaid_expense_account_id,a.account_id) AND account_type IN('opex','cogs','other_expense') AND is_active) THEN RAISE EXCEPTION 'Expense account required';END IF;
cur:=date_trunc('month',firstdate)::date;lastmonth:=date_trunc('month',lastdate)::date;INSERT INTO prepaid_schedules(tenant_id,source_bill_id,supplier_id,supplier_account_id,venue_id,description,total_amount,prepaid_account_id,expense_account_id,start_period,num_periods,amount_remaining,status) VALUES(t,b.id,b.supplier_id,b.supplier_account_id,b.venue_id,coalesce(a.notes,r.name,'Advance contract'),a.amount,pre,coalesce(a.prepaid_expense_account_id,a.account_id),cur,months,0,'active') RETURNING * INTO s;remaining:=a.amount;
WHILE cur<=lastmonth LOOP part:=CASE WHEN cur=lastmonth THEN remaining ELSE round(a.amount*(least(lastdate,(cur+interval '1 month -1 day')::date)-greatest(firstdate,cur)+1)/days,2) END;INSERT INTO prepaid_schedule_lines(tenant_id,schedule_id,period,planned_amount) VALUES(t,s.id,cur,part);remaining:=remaining-part;cur:=(cur+interval '1 month')::date;END LOOP;UPDATE expense_bill_allocations SET prepaid_schedule_id=s.id,prepaid_expense_account_id=coalesce(prepaid_expense_account_id,account_id),account_id=pre WHERE tenant_id=t AND id=a.id;n:=n+1;END LOOP;RETURN n;END $$;
REVOKE ALL ON FUNCTION public.finance_advance_contract_prepare(uuid,uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.finance_advance_contract_prepare(uuid,uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.finance_advance_contract_funded() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.approval_status='posted' AND OLD.approval_status IS DISTINCT FROM 'posted' THEN UPDATE public.prepaid_schedules s SET initial_journal_entry_id=NEW.journal_entry_id,amount_remaining=s.total_amount WHERE s.tenant_id=NEW.tenant_id AND s.source_bill_id=NEW.id AND s.status='active' AND s.initial_journal_entry_id IS NULL AND EXISTS(SELECT 1 FROM public.expense_bill_allocations a WHERE a.bill_id=NEW.id AND a.tenant_id=NEW.tenant_id AND a.prepaid_schedule_id=s.id AND a.account_id=s.prepaid_account_id AND a.amount=s.total_amount);END IF;RETURN NEW;END $$;
CREATE TRIGGER finance_advance_contract_funded AFTER UPDATE OF approval_status ON public.expense_bills FOR EACH ROW EXECUTE FUNCTION public.finance_advance_contract_funded();
DO $$ DECLARE def text;BEGIN SELECT pg_get_functiondef('public.expense_month_approve(uuid,date,jsonb)'::regprocedure) INTO def;IF position('AND is_contract)' IN def)=0 THEN RAISE EXCEPTION 'Contract monthly approval anchor unavailable';END IF;def:=replace(def,'AND is_contract)','AND is_contract AND billed_when<>''advance'')');EXECUTE def;END $$;